#!/usr/bin/env python3
"""test_lcd_js.py -- the page's renderer for the alpha's live LCD view, run under node and held to lcd.py, pixel for pixel (2026-11-04).

The dashboard of an image with the alpha's LCD draws the glass in a canvas from what GET /api/lcd answers: two rows of 16 codes and the
eight CGRAM slots, as hex (src/display/LcdGlassJson.h). WebUI.h carries the renderer in the JS of its `@IF lcd` block, in two pieces
this test cuts out by their markers:

  * the font block, `/* @LCD_FONT_BEGIN (generated by tools/lcd_alpha/fonte_web.py) */ ... /* @LCD_FONT_END */`: the glyphs of codes 0x20 to
    0x7F, seven rows each (row 7 of the 5 x 8 cell is always 0), from ROM_A00 of rom_hd44780.py (Hitachi's HD44780U table, the one lcd.py draws with by default; the Rights paragraph of that file says what it means that the page carries it);
  * the pure part, `/* lcd: the pure part of the renderer */ ... /* lcd: end of the pure part */`: LCD_STYLE (the colours and the
    geometry, one object, as lcd.py's Estilo), lcdSize( ), lcdFont( ), lcdDecode( ), lcdGlyph( ) and lcdPaint( ).

The cases run twice under node, as written and as the build's own minifier leaves it (tools/test_webui_minify.py tells why: the minifier
has deleted shipped code before and reported success). Each frame is drawn by the page's code into an RGBA buffer and compared byte for byte
with lcd.desenhar(rows, cgram), lcd.py's DEFAULT table, so the test proves page == print virtual: the 17 samples of the radio build and the 13 of the cable build (host_lcd.py builds them from
AlphaFrame.h), the link glyph of each of the 14 RSSIs of each network (slot 7, with code 7 and its mirror 15 in cells), the 96 codes of the font
(three frames), and a frame of the 16 codes 0 to 15 and back, which holds the CGRAM mirror. Answers that are not a glass (a row of 15 bytes, a
letter that is not hex, ...) must be refused, and a buffer too small for the image must be refused.

ONE DELIBERATE DIFFERENCE from lcd.py. A code with no glyph (0x10 to 0x1F and 0x80 to 0xFF: ROM_A00 has the 96 codes 0x20 to 0x7F) makes lcd.py raise, so the
manual's figures cannot silently show a wrong character. The page draws what the module draws for an empty cell: every dot of the cell unlit,
and does not throw (a live view that dies on one stray byte is worse than a blank cell). The expected image of those frames is lcd.py's with
ROM_A00 completed by 160 glyphs of zero rows, and says so in the report. Every other frame is lcd.py's with NO fonte argument, its default table
(no fallback needed: lcd.py draws them as they are).

MUTATION CONTROLS: the JS is copied and broken one way at a time (a colour off by one, a gap off by one, the margin, the dot, the bit
order reversed, the CGRAM mirror broken two ways, the font read one row off, a glyph with its rows shifted, the block made from another table (a dot of one glyph changed, two glyphs swapped, every glyph mirrored), the alpha, the fallback lit,
the fallback throwing, the checks of the answer taken out) and each copy must fail at least one case. The report names the first case
that caught it. An anchor that is not found exactly once fails the run: a mutant must be killed by a case and not by a typo.

The tool that writes the font block, fonte_web.py, is held here too: --check on the tree, on a copy with one digit changed (exit 1), on a
copy without the markers (exit 1); --write puts the block back byte for byte and twice gives the same file; the tool refuses a table
whose row 7 is not 0, a table with a code missing and a row that does not fit 5 dots.

  python3 tools/lcd_alpha/test_lcd_js.py

Exit 0 when every check holds, 1 when one fails, 2 when it cannot run (node, g++ or Pillow absent). Python 3.11 and later.
"""
import dataclasses
import functools
import json
import pathlib
import re
import shutil
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
HERE = pathlib.Path(__file__).resolve().parent
REPO = HERE.parents[1]
sys.path.insert(0, str(HERE))        # explicit: python3 -I leaves the script's own folder off the path (lcd.py, rom_hd44780.py, host_lcd.py)

WEBUI = REPO / 'WebUI.h'
BUILD_GZ = REPO / 'tools' / 'build_webui_gz.py'
FONTE_WEB = HERE / 'fonte_web.py'

FONT_BEGIN = '/* @LCD_FONT_BEGIN (generated by tools/lcd_alpha/fonte_web.py) */'
FONT_END = '/* @LCD_FONT_END */'
PURE_BEGIN = '/* lcd: the pure part of the renderer */'
PURE_END = '/* lcd: end of the pure part */'

LARGURA, ALTURA = 639, 137

CONTA = [0]
FALHAS = []


class NaoRoda(Exception):
    """The test cannot run: node, g++ or Pillow is missing, or the samples do not build. Exit 2."""


def confere(cond, msg, detalhe=''):
    CONTA[0] += 1
    if cond:
        print(f'  ok   {msg}')
    else:
        FALHAS.append(msg)
        print(f'  FAIL {msg}' + (f' ({detalhe})' if detalhe else ''))
    return bool(cond)


# ---- the page's code, cut out of WebUI.h --------------------------------------------------------------------------------------------------------
def pedacos(src):
    """(font block, pure part) of WebUI.h, each from its begin marker to its end marker, or None for the one that is not there exactly once."""
    def um(a, b):
        if src.count(a) != 1 or src.count(b) != 1:
            return None
        i, j = src.find(a), src.find(b)
        return src[i:j + len(b)] if i < j else None
    return um(FONT_BEGIN, FONT_END), um(PURE_BEGIN, PURE_END)


def bloco_if(src, pos):
    """The feature named by the /* @IF x */ ... /* @ENDIF */ block that holds position `pos`, or None."""
    for m in re.finditer(r'[ \t]*/\*\s*@IF\s+(!?\w+)\s*\*/[^\n]*\n(.*?)[ \t]*/\*\s*@ENDIF\s*\*/', src, re.S):
        if m.start(2) <= pos < m.end(2):
            return m.group(1)
    return None


def pagina_de(src, pos):
    last = None
    for m in re.finditer(r'static const char (\w+)\[\] PROGMEM', src):
        if m.start() > pos:
            break
        last = m.group(1)
    return last


@functools.lru_cache(maxsize=None)
def gerador():
    """build_webui_gz.py's functions, loaded without running its generate( ) (as tools/test_webui_theme_names.py does)."""
    ns = {'__name__': 'build_webui_gz'}
    exec(compile(BUILD_GZ.read_text(encoding='utf-8').replace('\ngenerate()\n', '\n'), str(BUILD_GZ), 'exec'), ns)
    return ns


def sem_comentarios(js):
    return re.sub(r'/\*.*?\*/', ' ', js, flags=re.S)


# ---- the frames and what lcd.py draws for them -------------------------------------------------------------------------------------------------
def dois_hex(b):
    return b.hex()


def quadro_json(linhas, cgram):
    """What GET /api/lcd answers, as the page receives it (parsed): linhas, cgram, and the two counters the renderer ignores."""
    return {'linhas': [dois_hex(l) for l in linhas], 'cgram': [dois_hex(s) for s in cgram], 'seq': 2, 'age_ms': 7}


def slots_variados():
    """Eight CGRAM slots that differ from each other, with bits 5 to 7 set in some rows (the controller ignores them, so must the page)."""
    out = []
    for k in range(8):
        out.append(bytes(((k * 5 + r * 3 + 1) & 0x1F) | (0xE0 if (k + r) % 5 == 0 else 0) for r in range(8)))
    return out


def construir_quadros():
    """[{id, json, expect, rgba}]: the cases. `expect` is 'draw' (rgba is lcd.py's image) or 'throw' (the answer is not a glass)."""
    import lcd
    import rom_hd44780
    import host_lcd
    completa = dict(rom_hd44780.ROM_A00)
    completa.update({c: (0,) * 8 for c in range(16, 256) if c not in completa})   # the deliberate difference: every dot of the cell unlit
    quadros = []

    def desenha(linhas, cgram, fonte):
        # fonte None is lcd.py's DEFAULT table, ROM_A00, the one the manual's figures are drawn with: a frame is held to the print virtual itself
        if fonte is None:
            return lcd.desenhar(tuple(linhas), list(cgram)).convert('RGBA').tobytes()
        return lcd.desenhar(tuple(linhas), list(cgram), fonte=fonte).convert('RGBA').tobytes()

    def draw(id_, linhas, cgram, fonte=None):
        quadros.append({'id': id_, 'json': quadro_json(linhas, cgram), 'expect': 'draw', 'rgba': desenha(linhas, cgram, fonte)})

    for rede in ('wifi', 'cabo'):
        try:
            amostras, icones = host_lcd.quadros(rede, host_lcd.VERSAO_DO_TESTE)
        except host_lcd.Falta as e:
            raise NaoRoda(f'the samples of the {rede} build cannot be made: {e}')
        for nome, (linhas, cgram) in sorted(amostras.items()):
            draw(f'{rede}/{nome}', linhas, cgram)
        slots = slots_variados()[:7]
        for rssi, glifo in sorted(icones.items()):
            linha0 = bytes(range(8)) + b'dBm ' + bytes([7, 15, 7, 15])
            linha1 = f'{rssi} dBm'.ljust(16).encode('ascii')
            draw(f'{rede}/icone{rssi}', (linha0, linha1), slots + [glifo])
    todos = bytes(range(0x20, 0x80))
    for k in range(3):
        c = todos[k * 32:(k + 1) * 32]
        draw(f'fonte/{c[0]:02x}-{c[-1]:02x}', (c[:16], c[16:]), slots_variados())
    draw('cgram/espelho', (bytes(range(16)), bytes(range(15, -1, -1))), slots_variados())
    draw('fallback/10-1f+80-8f', (bytes(range(0x10, 0x20)), bytes(range(0x80, 0x90))), slots_variados(), completa)
    draw('fallback/a0-ff-misturado', (b'ABC' + bytes([0xA0, 0xDF, 0xFF]) + b'xyz' + bytes([0x1F, 0x10, 0x00]) + b'09~!', bytes(range(0xE0, 0xF0))),
         slots_variados(), completa)
    ok = [h.hex() for h in slots_variados()]
    base = {'linhas': ['20' * 16, '20' * 16], 'cgram': ok, 'seq': 2, 'age_ms': 7}

    def ruim(id_, **mudanca):
        j = dict(base)
        j.update(mudanca)
        quadros.append({'id': id_, 'json': j, 'expect': 'throw', 'rgba': None})

    ruim('ruim/linha-curta', linhas=['20' * 15, '20' * 16])
    ruim('ruim/linha-longa', linhas=['20' * 16, '20' * 17])
    ruim('ruim/uma-linha', linhas=['20' * 16])
    ruim('ruim/tres-linhas', linhas=['20' * 16] * 3)
    ruim('ruim/hex-invalido', linhas=['zz' + '20' * 15, '20' * 16])
    ruim('ruim/hex-impar', linhas=['2' * 33, '20' * 16])
    ruim('ruim/cgram-sete', cgram=ok[:7])
    ruim('ruim/cgram-slot-curto', cgram=ok[:7] + ['00' * 7])
    ruim('ruim/linha-nao-texto', linhas=[None, '20' * 16])
    ruim('ruim/sem-linhas', linhas=None)
    ruim('ruim/sem-cgram', cgram=None)
    ruim('ruim/vazio', linhas=[], cgram=[])
    quadros.append({'id': 'ruim/nulo', 'json': None, 'expect': 'throw', 'rgba': None})
    return quadros


# ---- node ---------------------------------------------------------------------------------------------------------------------------------------
HARNESS = r"""
const __fs = require('fs'), __path = require('path');
const __job = JSON.parse(__fs.readFileSync(process.argv[2], 'utf8'));
const __out = process.argv[3];
const __res = { frames: {}, meta: {} };
try {
    const __font = lcdFont(LCD_FONT_HEX);
    __res.meta = { fontLen: __font.length, rowSeven: __font.every(function (g) { return g.length === 8 && g[7] === 0; }),
                   style: LCD_STYLE, size: lcdSize(LCD_STYLE) };
    __job.frames.forEach(function (f, n) {
        try {
            const d = lcdDecode(f.json);
            const sz = lcdSize(LCD_STYLE);
            const px = new Uint8ClampedArray(sz[0] * sz[1] * 4);
            lcdPaint(px, d.rows, d.cgram, __font);
            __fs.writeFileSync(__path.join(__out, n + '.rgba'), px);
            __res.frames[f.id] = { ok: true, file: n + '.rgba' };
        } catch (e) { __res.frames[f.id] = { ok: false, error: String((e && e.message) || e) }; }
    });
    const __sp = function () { return new Uint8Array(16).fill(0x20); };   /* spaces: the font path, so only the buffer guard can refuse */
    try { lcdPaint(new Uint8ClampedArray(16), [__sp(), __sp()], [], __font); __res.meta.smallBufferRefused = false; }
    catch (e) { __res.meta.smallBufferRefused = true; }
} catch (e) { __res.fatal = String((e && e.stack) || e); }
console.log(JSON.stringify(__res));
"""


def node():
    n = shutil.which('node') or shutil.which('nodejs')
    if not n:
        raise NaoRoda('node is not installed: the renderer cannot be exercised (CI\'s runner has it)')
    return n


def roda(codigo, quadros):
    """Runs `codigo` (the page's JS) over the frames under node. Returns (result dict, {id: RGBA bytes drawn}), or (None, why) when node fails."""
    with tempfile.TemporaryDirectory(prefix='test_lcd_js_') as tmp:
        tmp = pathlib.Path(tmp)
        (tmp / 'job.json').write_text(json.dumps({'frames': [{'id': q['id'], 'json': q['json']} for q in quadros]}), encoding='utf-8')
        (tmp / 'run.js').write_text(codigo + '\n' + HARNESS, encoding='utf-8')
        saida = tmp / 'px'
        saida.mkdir()
        r = subprocess.run([node(), str(tmp / 'run.js'), str(tmp / 'job.json'), str(saida)], capture_output=True, text=True, timeout=120)
        if r.returncode != 0:
            return None, (r.stderr or r.stdout)[-1200:]
        try:
            res = json.loads(r.stdout.strip().splitlines()[-1])
        except (ValueError, IndexError):
            return None, 'node printed no result: ' + (r.stdout + r.stderr)[-600:]
        if 'fatal' in res:
            return None, res['fatal'][-1200:]
        px = {i: (saida / f['file']).read_bytes() for i, f in res['frames'].items() if f.get('ok')}
        return res, px


def primeira_diferenca(a, b, largura=LARGURA):
    """None when equal, else a sentence naming the first byte that differs: the pixel (x, y) and both RGBA values, or the sizes."""
    if len(a) != len(b):
        return f'{len(a)} bytes drawn, {len(b)} expected'
    if a == b:
        return None
    for i in range(0, len(a), 4):
        if a[i:i + 4] != b[i:i + 4]:
            p = i // 4
            return f'pixel ({p % largura}, {p // largura}) is {a[i:i + 4].hex()}, lcd.py has {b[i:i + 4].hex()}'
    return 'differs'


def problemas(res, px, quadros):
    """The cases that fail: [(id, why)]."""
    out = []
    for q in quadros:
        r = res['frames'].get(q['id'])
        if r is None:
            out.append((q['id'], 'no result'))
        elif q['expect'] == 'throw':
            if r.get('ok'):
                out.append((q['id'], 'an answer that is not a glass was drawn'))
        elif not r.get('ok'):
            out.append((q['id'], 'threw: ' + r.get('error', '?')))
        else:
            d = primeira_diferenca(px[q['id']], q['rgba'])
            if d:
                out.append((q['id'], d))
    meta = res['meta']
    if meta.get('smallBufferRefused') is not True:
        out.append(('buffer', 'a buffer too small for the image was drawn into'))
    if meta.get('size') != [LARGURA, ALTURA]:
        out.append(('size', f'lcdSize( ) says {meta.get("size")}, the canvas is {LARGURA} x {ALTURA}'))
    return out


def estilo_esperado():
    import lcd
    e = lcd.Estilo()
    return {'bg': list(e.fundo), 'lit': list(e.aceso), 'unlit': list(e.apagado), 'dot': e.ponto, 'dotGap': e.vao_ponto,
            'cellGap': e.vao_char, 'rowGap': e.vao_linha, 'margin': e.margem}


def roda_e_confere(rotulo, codigo, quadros):
    if codigo is None:
        confere(False, f'{rotulo}: the renderer is in WebUI.h', 'its markers are missing or not once each')
        return False
    res, px = roda(codigo, quadros)
    if res is None:
        confere(False, f'{rotulo}: node runs the page code', str(px))
        return False
    ruins = problemas(res, px, quadros)
    n_draw = sum(1 for q in quadros if q['expect'] == 'draw')
    n_throw = len(quadros) - n_draw
    ok = confere(not ruins, f'{rotulo}: {n_draw} frames equal lcd.py pixel for pixel, {n_throw} answers that are not a glass refused, a small buffer refused',
                 '; '.join(f'{i}: {w}' for i, w in ruins[:4]) + (f' ... and {len(ruins) - 4} more' if len(ruins) > 4 else ''))
    meta = res['meta']
    ok &= confere(meta.get('fontLen') == 96 and meta.get('rowSeven') is True,
                  f'{rotulo}: the font block decodes to 96 glyphs of 8 rows with row 7 blank (no code past 0x7F)', str(meta.get('fontLen')))
    ok &= confere(meta.get('style') == estilo_esperado(), f'{rotulo}: LCD_STYLE (one object) holds the colours and the geometry of lcd.Estilo', str(meta.get('style')))
    return ok


# ---- the mutants ---------------------------------------------------------------------------------------------------------------------------------
def mutantes(rom, fonte_web, fonte_js):
    """[(name, where, find, replace)]: where is 'pure' or 'font'. The glyph of 'A' is found by its rows, from the table and not from the file; the last three font
    mutants replace the whole block by one that fonte_web.bloco( ) makes from another table (a dot of one glyph, two glyphs swapped, every glyph mirrored)."""
    a = rom.ROM_A00[0x41]
    rows = ''.join(f'{v:02X}' for v in a[:7])
    deslocada = ''.join(f'{v:02X}' for v in (0,) + tuple(a[:6]))

    def outra(alterar):
        t = dict(rom.ROM_A00)
        alterar(t)
        return fonte_web.bloco(t, rom.TABLE_SHA256)

    def um_ponto(t):
        g = t[0x4D]
        t[0x4D] = g[:3] + (g[3] ^ 0b00100,) + g[4:]

    def trocadas(t):
        t[0x4F], t[0x30] = t[0x30], t[0x4F]

    def espelhada(t):
        for c in list(t):
            t[c] = tuple(int(format(v, '05b')[::-1], 2) for v in t[c])
    return [
        ('colour off by one: lit red 0xEE -> 0xEF', 'pure', '0xEE', '0xEF'),
        ('colour off by one: unlit green 0x5C -> 0x5D', 'pure', '0x5C', '0x5D'),
        ('colour off by one: background blue 0xC8 -> 0xC9', 'pure', '0xC8', '0xC9'),
        ('gap off by one: dotGap 1 -> 2', 'pure', 'dotGap: 1', 'dotGap: 2'),
        ('gap off by one: dotGap 1 -> 0', 'pure', 'dotGap: 1', 'dotGap: 0'),
        ('gap off by one: cellGap 5 -> 4', 'pure', 'cellGap: 5', 'cellGap: 4'),
        ('gap off by one: rowGap 7 -> 6', 'pure', 'rowGap: 7', 'rowGap: 6'),
        ('margin 10 -> 11', 'pure', 'margin: 10', 'margin: 11'),
        ('dot 6 -> 5', 'pure', 'dot: 6', 'dot: 5'),
        ('bit order reversed (bit 0 the leftmost dot)', 'pure', '(0x10 >> j)', '(1 << j)'),
        ('CGRAM mirror broken: code & 7 -> code & 3', 'pure', 'cgram[code & 7]', 'cgram[code & 3]'),
        ('CGRAM mirror broken: codes 8 to 15 left to the font', 'pure', 'code < 16', 'code < 8'),
        ('font read one row off (every glyph)', 'pure', '(c * 7 + r) * 2', '(c * 7 + r + 1) * 2'),
        ('font data: the rows of "A" shifted down by one', 'font', rows, deslocada),
        ('font data: the block made from a table with one dot of "M" changed', 'font', fonte_js, outra(um_ponto)),
        ('font data: the block made from a table with "O" and "0" swapped', 'font', fonte_js, outra(trocadas)),
        ('font data: the block made from a table with every glyph mirrored left to right', 'font', fonte_js, outra(espelhada)),
        ('alpha 255 -> 254', 'pure', 'px[o + 3] = 255', 'px[o + 3] = 254'),
        ('fallback: a code with no glyph draws every dot lit', 'pure', 'const LCD_BLANK = new Uint8Array(8);', 'const LCD_BLANK = new Uint8Array(8).fill(31);'),
        ('fallback: a code with no glyph throws', 'pure', ': LCD_BLANK;', ': font[code - 0x20];'),
        ('answer check out: the length of a row', 'pure', ' || s.length !== n', ''),
        ('answer check out: the hex digits', 'pure', ' || !/^[0-9a-fA-F]*$/.test(s)', ''),
        ('answer check out: the number of rows', 'pure', ' || d.linhas.length !== 2', ''),
        ('answer check out: the number of slots', 'pure', ' || d.cgram.length !== 8', ''),
        ('buffer check out: a small buffer is drawn into', 'pure', 'px.length < ', 'px.length < 0 * '),
    ]


def aplica(fonte_js, puro_js, onde, achar, trocar):
    alvo = fonte_js if onde == 'font' else puro_js
    n = alvo.count(achar)
    if n != 1:
        return None, f'the anchor {achar!r} is found {n} times in the {onde} part, not once'
    novo = alvo.replace(achar, trocar)
    return (novo + '\n' + puro_js, None) if onde == 'font' else (fonte_js + '\n' + novo, None)


# ---- what node cannot see ------------------------------------------------------------------------------------------------------------------------
def fiacao(src, fonte_js, puro_js):
    confere(fonte_js is not None, 'W1 the font block is in WebUI.h once, between its @LCD_FONT markers')
    confere(puro_js is not None, 'W2 the renderer\'s pure part is in WebUI.h once, between the lcd: comments')
    if fonte_js is None or puro_js is None:
        return
    i, j = src.find(FONT_BEGIN), src.find(PURE_BEGIN)
    confere(i < j and bloco_if(src, i) == 'lcd' and bloco_if(src, j) == 'lcd',
            'W3 both pieces sit inside /* @IF lcd */ blocks (the other images cut them; the alpha and the cable build keep them)',
            f'font in @IF {bloco_if(src, i)}, renderer in @IF {bloco_if(src, j)}')
    confere(pagina_de(src, i) == 'DASH_PAGE' and pagina_de(src, j) == 'DASH_PAGE', 'W4 both pieces are in DASH_PAGE, the page that draws the box')
    codigo = sem_comentarios(fonte_js) + sem_comentarios(puro_js)
    impuro = [p for p in (r'\bdocument\b', r'\bwindow\b', r'\bfetch\b', r'\bsetTimeout\b', r'\bsetInterval\b', r'\bperformance\b', r'\bt\s*\(') if re.search(p, codigo)]
    confere(not impuro, 'W5 the pure part and the font block touch no page, no clock and no network (and call no t( ): nothing to translate)', ', '.join(impuro))
    confere('rom_hd44780.py' in fonte_js and 'ROM_A00' in fonte_js and 'Rights paragraph' in fonte_js,
            "W6 the font block names its source, ROM_A00 of rom_hd44780.py, and points to that file's Rights paragraph (the table is Hitachi's, and the page carries it)")
    confere(len(re.findall(r'LCD_STYLE\s*=', codigo)) == 1, 'W7 the colours and the geometry are one object, LCD_STYLE, defined once')


def ferramenta():
    """fonte_web.py: the generator of the font block, held on copies of WebUI.h in a scratch folder (the tree's own is never written)."""
    if not FONTE_WEB.exists():
        confere(False, 'T0 tools/lcd_alpha/fonte_web.py exists')
        return
    import rom_hd44780

    def cli(*args, webui=None):
        cmd = [sys.executable, '-I', str(FONTE_WEB), *args] + (['--webui', str(webui)] if webui else [])
        return subprocess.run(cmd, capture_output=True, text=True, timeout=60)

    r = cli('--check')
    confere(r.returncode == 0, 'T1 fonte_web.py --check: the block in WebUI.h is what rom_hd44780.py says', (r.stdout + r.stderr).strip()[-300:])
    src = WEBUI.read_text(encoding='utf-8')
    fonte_js, _ = pedacos(src)
    if fonte_js is None:
        confere(False, 'T2 the font block is there to be changed')
        return
    with tempfile.TemporaryDirectory(prefix='test_lcd_js_tool_') as tmp:
        tmp = pathlib.Path(tmp)
        copia = tmp / 'WebUI.h'
        m = re.search(r"'([0-9A-F]{200,})'", fonte_js)
        if not m:
            confere(False, 'T2 the font block holds its digits as quoted hex strings (a row of 16 glyphs each)')
            return
        i = src.find(FONT_BEGIN) + m.start(1) + 40      # m is a match in the block, i a position in the file
        trocado = src[:i] + ('0' if src[i] != '0' else '1') + src[i + 1:]
        copia.write_text(trocado, encoding='utf-8')
        r = cli('--check', webui=copia)
        confere(r.returncode == 1, 'T2 --check on a copy with one hex digit of the block changed exits 1', f'exit {r.returncode}: {(r.stdout + r.stderr).strip()[-200:]}')
        sem = tmp / 'sem.h'
        sem.write_text(src.replace(FONT_END, '/* gone */'), encoding='utf-8')
        r = cli('--check', webui=sem)
        confere(r.returncode == 1, 'T3 --check on a copy without the end marker exits 1', f'exit {r.returncode}')
        r = cli('--write', webui=copia)
        confere(r.returncode == 0 and copia.read_text(encoding='utf-8') == src, 'T4 --write on the changed copy puts the block back, byte for byte', f'exit {r.returncode}')
        antes = copia.read_bytes()
        cli('--write', webui=copia)
        confere(copia.read_bytes() == antes, 'T5 --write twice gives the same file')
        r = cli('--check', webui=copia)
        confere(r.returncode == 0, 'T6 --check on the written copy exits 0')
        r = cli('--check', webui=tmp / 'nao-existe.h')
        confere(r.returncode == 2, 'T7 --check on a file that is not there exits 2 (cannot run), not 0', f'exit {r.returncode}')
    try:
        import fonte_web
    except ImportError as e:
        confere(False, 'T8 fonte_web.py can be imported by the tests', str(e))
        return
    tabela = dict(rom_hd44780.ROM_A00)

    def recusa(t, quer):
        try:
            fonte_web.codificar(t)
        except ValueError as e:
            return quer in str(e)
        return False

    t1 = dict(tabela)
    t1[0x41] = tabela[0x41][:7] + (1,)
    confere(recusa(t1, 'row 7'), 'T8 the encoder refuses a table whose row 7 is not 0 (and names row 7)')
    t2 = dict(tabela)
    del t2[0x50]
    confere(recusa(t2, '0x50'), 'T9 the encoder refuses a table with a code missing (and names it)')
    t3 = dict(tabela)
    t3[0x42] = (0x20,) + tabela[0x42][1:]
    confere(recusa(t3, '0x42'), 'T10 the encoder refuses a row that does not fit the 5 dots (and names the code)')
    t4 = dict(tabela)
    t4[0x80] = (0,) * 8
    confere(recusa(t4, '0x80'), 'T11 the encoder refuses a code past 0x7F (the page has 96 glyphs)')
    h = fonte_web.codificar(tabela)
    esperado = ''.join(f'{v:02X}' for c in range(0x20, 0x80) for v in tabela[c][:7])
    confere(h == esperado and len(h) == 96 * 7 * 2, 'T12 the encoding is the 7 rows of each code from 0x20, two upper-case hex digits a row (1344 digits)')


def main():
    try:
        import lcd          # noqa: F401  (Pillow)
        import rom_hd44780  # noqa: F401
        import host_lcd     # noqa: F401
    except ImportError as e:
        print(f'test_lcd_js.py: cannot run: {e} (Pillow is needed to draw lcd.py\'s images: pip install pillow)', file=sys.stderr)
        return 2
    try:
        node()
        src = WEBUI.read_text(encoding='utf-8', errors='replace')
        fonte_js, puro_js = pedacos(src)
        print('wiring')
        fiacao(src, fonte_js, puro_js)
        print('the page code under node')
        quadros = construir_quadros()
        codigo = None if fonte_js is None or puro_js is None else fonte_js + '\n' + puro_js
        roda_e_confere('as written', codigo, quadros)
        mini = None
        if codigo is not None:
            try:
                mini = gerador()['_minify_js'](codigo)
            except Exception as e:   # the minifier refusing is a failure of this check
                confere(False, 'minified: the build\'s minifier takes the code', f'{type(e).__name__}: {e}')
        if mini is not None:
            roda_e_confere('minified', mini, quadros)
        print('the instrument')
        igual = bytes(range(256)) * 4
        um = bytearray(igual)
        um[4 * (3 * LARGURA + 5) % len(um)] ^= 1
        confere(primeira_diferenca(igual, igual) is None and primeira_diferenca(bytes(um), igual) is not None and primeira_diferenca(igual[:-4], igual) is not None,
                'I1 the comparison names a difference of one bit and a difference of size, and passes equal buffers')
        q0 = quadros[0]
        torto = dict(q0)
        torto['rgba'] = bytearray(q0['rgba'])
        torto['rgba'][4 * (50 * LARGURA + 100)] ^= 1
        if codigo is not None:
            res, px = roda(codigo, [q0, torto])
            confere(res is not None and len(problemas(res, px, [q0, torto])) == 1,
                    'I2 a frame whose expected image has one bit wrong fails exactly that case (the cases can fail)')
        print('mutation controls')
        if codigo is None:
            confere(False, 'M0 the mutants need the renderer in WebUI.h')
        else:
            import fonte_web as fw
            import rom_hd44780 as rom
            n_matou = 0
            ms = mutantes(rom, fw, fonte_js)
            for nome, onde, achar, trocar in ms:
                novo, erro = aplica(fonte_js, puro_js, onde, achar, trocar)
                if novo is None:
                    confere(False, f'M {nome}', erro)
                    continue
                res, px = roda(novo, quadros)
                if res is None:
                    # a mutant that stops node altogether is killed by the run, not by a case: the report says so
                    n_matou += confere(True, f'M {nome}: killed (node stopped: {str(px).strip().splitlines()[-1][:90] if str(px).strip() else "?"})')
                    continue
                ruins = problemas(res, px, quadros)
                n_matou += confere(bool(ruins), f'M {nome}: killed by {len(ruins)} case(s), the first {ruins[0][0] if ruins else "-"}',
                                   'the mutant passes every case')
            print(f'  {n_matou} of {len(ms)} mutants killed')
        print('the font block tool')
        ferramenta()
    except NaoRoda as e:
        print(f'test_lcd_js.py: cannot run: {e}', file=sys.stderr)
        return 2
    print(f'{CONTA[0]} checks, {len(FALHAS)} failed')
    for f in FALHAS:
        print(f'  FAILED: {f}')
    return 1 if FALHAS else 0


if __name__ == '__main__':
    sys.exit(main())
